-- Step 4: Invites (Card 1), Password resets (Card 2) and unique display names (Card 3 rule 5, changed 2026-10-11).
-- Ids are uuid v7, generated by the Go code. Tokens are stored only as hashes.

-- +goose Up
-- One row per Invite. Its status is worked out from these columns: Accepted when accepted_at is set, Cancelled when
-- cancelled_at is set, otherwise Expired once expires_at has passed, else Pending. Resending gives the same row a new
-- token_hash and expires_at.
CREATE TABLE invites (
    id           uuid PRIMARY KEY,
    email        citext      NOT NULL,
    role         user_role   NOT NULL,
    token_hash   text        NOT NULL UNIQUE,
    -- Users are deactivated, never deleted, so this never cascades.
    invited_by   uuid        NOT NULL REFERENCES users (id),
    expires_at   timestamptz NOT NULL,
    accepted_at  timestamptz,
    cancelled_at timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    CHECK (accepted_at IS NULL OR cancelled_at IS NULL)
);

-- At most one open (Pending or Expired) Invite per email: a new Invite cancels the open one first (Card 1 edge case).
CREATE UNIQUE INDEX invites_open_email_idx ON invites (email) WHERE accepted_at IS NULL AND cancelled_at IS NULL;

-- One row per reset link sent. Only a User's newest unused, unexpired token works (Card 2 rule 8 and edge case), and
-- the rows of the last hour cap reset emails at 3 per User (clarified 2026-10-11).
CREATE TABLE password_reset_tokens (
    id         uuid PRIMARY KEY,
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash text        NOT NULL UNIQUE,
    expires_at timestamptz NOT NULL,
    used_at    timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX password_reset_tokens_user_id_created_at_idx ON password_reset_tokens (user_id, created_at);

-- No two Users share a display name, ignoring case. This fails if two existing Users already do.
CREATE UNIQUE INDEX users_display_name_lower_idx ON users (lower(display_name));

-- +goose Down
DROP INDEX users_display_name_lower_idx;
DROP TABLE password_reset_tokens;
DROP TABLE invites;
